/**
 * The packed cost model prices a VALUES-driven statement pattern through per-row {@code finite_binding_probe}
 * cardinality probes. Since the bounded page estimator replaced the exhaustive page walk, those probes are sampled for
 * large ranges, so the evidence guarantee published on the planned node must follow the estimator's exactness instead
 * of being asserted {@code database_exact} unconditionally.
 */
class LmdbFiniteProbeExactnessLabelTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NS = "http://example.org/finite-probe/";
	private static final IRI BIG = VF.createIRI(NS, "big");
	private static final IRI HUB = VF.createIRI(NS, "hub");
	private static final String FINITE_LOOKUP_SOURCE = "lmdb-finite-binding-lookup";
	private static final String GUARANTEE_METRIC = "plannedFrontierGuarantee";
	private static final String PROBE_EXACT_METRIC = "plannedFiniteProbeExact";
	private static final int SAMPLED_HUB_ROWS = 40_000;

	@Test
	void sampledFiniteProbeIsNotLabelledDatabaseExact(@TempDir File dataDir) throws Exception {
		LmdbStore store = frontierOffStore(dataDir);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			/*
			 * The range counter counts a range exactly when either the range itself or its complement fits the leaf
			 * budget, so both the hub range and the rest of the :big index must be far larger than that budget for the
			 * probe to be sampled.
			 */
			loadHub(repository, SAMPLED_HUB_ROWS, SAMPLED_HUB_ROWS);
			CardinalityEstimate probe = hubProbeEstimate(store);
			assertFalse(probe.exact(), "precondition: the page estimator must sample the hub range. estimate=" + probe);

			StatementPattern planned = planHubProbe(store);

			assertEquals(FINITE_LOOKUP_SOURCE,
					planned.getStringMetricPlanned(TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE),
					"the VALUES-driven pattern must be priced through the finite binding probe. metrics="
							+ planned.getStringMetricsPlanned());
			String guarantee = planned.getStringMetricPlanned(GUARANTEE_METRIC);
			assertNotEquals("database_exact", guarantee,
					"a sampled finite probe over " + SAMPLED_HUB_ROWS
							+ " rows must not be published as database-exact. estimate=" + probe + ", metrics="
							+ planned.getStringMetricsPlanned() + ", doubles=" + planned.getDoubleMetricsPlanned());
			assertNotNull(guarantee, "a sampled finite probe must still publish its (weaker) guarantee. metrics="
					+ planned.getStringMetricsPlanned());
			assertEquals(0.0d, planned.getDoubleMetricPlanned(PROBE_EXACT_METRIC), 0.0d,
					"explain output must say the probe was sampled. doubles=" + planned.getDoubleMetricsPlanned());
			assertTrue(planned.getDoubleMetricPlanned("plannedFrontierUpperRows") >= probe.hardLowerBound(),
					"a sampled probe publishes its hard bounds. doubles=" + planned.getDoubleMetricsPlanned());
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void exactFiniteProbeKeepsDatabaseExact(@TempDir File dataDir) throws Exception {
		LmdbStore store = frontierOffStore(dataDir);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			// A tiny range is walked exhaustively, so the probe is exact and the strong label is legitimate.
			loadHub(repository, 12, 64);
			CardinalityEstimate probe = hubProbeEstimate(store);
			assertTrue(probe.exact(), "precondition: a 12-row range is counted exhaustively. estimate=" + probe);

			StatementPattern planned = planHubProbe(store);

			assertEquals(FINITE_LOOKUP_SOURCE,
					planned.getStringMetricPlanned(TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE),
					"metrics=" + planned.getStringMetricsPlanned());
			assertEquals("database_exact", planned.getStringMetricPlanned(GUARANTEE_METRIC),
					"an exhaustively counted finite probe keeps its database-exact guarantee. metrics="
							+ planned.getStringMetricsPlanned());
			assertEquals(12.0d, planned.getResultSizeEstimate(), 0.0d);
			assertEquals(1.0d, planned.getDoubleMetricPlanned(PROBE_EXACT_METRIC), 0.0d,
					"doubles=" + planned.getDoubleMetricsPlanned());
		} finally {
			repository.shutDown();
		}
	}

	/**
	 * The page estimator and the bounded exact walk count the explicit and the inferred plane together, while the
	 * planned probe is shared by explicit-only and inferred-including queries (the plan version only carries the
	 * store-level "may have inferred rows" flag). A both-plane count is therefore only an upper bound for the query
	 * once the store holds inferred statements, so it must not be published as database-exact.
	 */
	@Test
	void exactFiniteProbeOverBothPlanesIsOnlyACertifiedBound(@TempDir File dataDir) throws Exception {
		LmdbStore store = frontierOffStore(dataDir);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			loadHub(repository, 12, 64);
			addInferred(store, HUB, BIG, VF.createIRI(NS, "inferred-hub-object"));
			CardinalityEstimate probe = hubProbeEstimate(store);
			assertTrue(probe.exact(), "precondition: a 13-row range is counted exhaustively. estimate=" + probe);
			assertEquals(13.0d, probe.entries(), 0.0d, "precondition: the probe counts both planes. estimate=" + probe);

			StatementPattern planned = planProbe(store, HUB);

			assertEquals(FINITE_LOOKUP_SOURCE,
					planned.getStringMetricPlanned(TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE),
					"metrics=" + planned.getStringMetricsPlanned());
			assertEquals("certified_bound_only", planned.getStringMetricPlanned(GUARANTEE_METRIC),
					"an explicit-only query sees only 12 of the 13 counted rows, so the count is an upper bound. "
							+ "metrics=" + planned.getStringMetricsPlanned());
			assertEquals(0.0d, planned.getDoubleMetricPlanned(PROBE_EXACT_METRIC), 0.0d,
					"doubles=" + planned.getDoubleMetricsPlanned());
			assertEquals(0.0d, planned.getDoubleMetricPlanned("plannedFrontierLowerRows"), 0.0d,
					"the explicit plane alone may hold none of the counted rows. doubles="
							+ planned.getDoubleMetricsPlanned());
			assertEquals(13.0d, planned.getDoubleMetricPlanned("plannedFrontierUpperRows"), 0.0d,
					"doubles=" + planned.getDoubleMetricsPlanned());
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void exactZeroFiniteProbeStaysDatabaseExactWithInferredRows(@TempDir File dataDir) throws Exception {
		LmdbStore store = frontierOffStore(dataDir);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			loadHub(repository, 12, 64);
			addInferred(store, HUB, BIG, VF.createIRI(NS, "inferred-hub-object"));
			// object-0 is a stored term that never occurs as a :big subject, in either plane.
			IRI absentSubject = VF.createIRI(NS, "object-0");

			StatementPattern planned = planProbe(store, absentSubject);

			assertEquals(FINITE_LOOKUP_SOURCE,
					planned.getStringMetricPlanned(TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE),
					"metrics=" + planned.getStringMetricsPlanned());
			assertEquals("database_exact", planned.getStringMetricPlanned(GUARANTEE_METRIC),
					"a zero over both planes is a zero over any plane subset. metrics="
							+ planned.getStringMetricsPlanned());
			assertEquals(0.0d, planned.getResultSizeEstimate(), 0.0d);
			assertEquals(1.0d, planned.getDoubleMetricPlanned(PROBE_EXACT_METRIC), 0.0d,
					"doubles=" + planned.getDoubleMetricsPlanned());
		} finally {
			repository.shutDown();
		}
	}

	private static LmdbStore frontierOffStore(File dataDir) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF);
		return new LmdbStore(dataDir, config);
	}

	private static void loadHub(SailRepository repository, int hubRows, int otherRows) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			for (int ordinal = 0; ordinal < hubRows; ordinal++) {
				connection.add(HUB, BIG, VF.createIRI(NS, "hub-object-" + ordinal));
			}
			for (int ordinal = 0; ordinal < otherRows; ordinal++) {
				connection.add(VF.createIRI(NS, "subject-" + ordinal), BIG, VF.createIRI(NS, "object-" + ordinal));
			}
			connection.commit();
		}
	}

	/** The estimator's own answer for the {@code HUB :big ?o} probe, so each test states its sampling precondition. */
	private static CardinalityEstimate hubProbeEstimate(LmdbStore store) throws Exception {
		TripleStore tripleStore = field(store, "tripleStore", TripleStore.class);
		ValueStore valueStore = field(store, "valueStore", ValueStore.class);
		long hub = valueStore.getId(HUB);
		long big = valueStore.getId(BIG);
		assertTrue(hub != LmdbValue.UNKNOWN_ID && big != LmdbValue.UNKNOWN_ID, "test terms must be stored");
		return tripleStore.planningCardinalityEstimate(hub, big, LmdbValue.UNKNOWN_ID, LmdbValue.UNKNOWN_ID);
	}

	private static <T> T field(LmdbStore store, String name, Class<T> type) throws Exception {
		Field field = LmdbSailStore.class.getDeclaredField(name);
		field.setAccessible(true);
		return type.cast(field.get(store.getBackingStore()));
	}

	private static void addInferred(LmdbStore store, IRI subject, IRI predicate, IRI object) {
		try (LmdbStoreConnection connection = (LmdbStoreConnection) store.getConnection()) {
			connection.begin();
			connection.addInferredStatement(subject, predicate, object);
			connection.commit();
		}
	}

	private static StatementPattern planHubProbe(LmdbStore store) {
		return planProbe(store, HUB);
	}

	private static StatementPattern planProbe(LmdbStore store, IRI subject) {
		BindingSetAssignment values = bindingAssignment("s", subject);
		StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("bigPredicate", BIG), Var.of("o"));
		EvaluationStatistics statistics = store.getBackingStore().getEvaluationStatistics();
		TupleExpr input = new Join(values, pattern);
		CascadesPlan plan = new LmdbCascadesOptimizer(statistics, false)
				.planPreparedInput(input, OptimizationGoal.root(input, PhysicalProperties.ANY));
		StatementPattern planned = findStatementPattern(plan.tupleExpr(), BIG, "o");
		assertTrue(planned != null, "expected the planned statement pattern. plan=" + plan.tupleExpr());
		return planned;
	}

	private static BindingSetAssignment bindingAssignment(String bindingName, Value... values) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		List<BindingSet> bindingSets = new ArrayList<>(values.length);
		for (Value value : values) {
			QueryBindingSet bindingSet = new QueryBindingSet();
			bindingSet.addBinding(bindingName, value);
			bindingSets.add(bindingSet);
		}
		assignment.setBindingSets(bindingSets);
		return assignment;
	}

	private static StatementPattern findStatementPattern(TupleExpr optimized, IRI predicate,
			String objectBindingName) {
		List<StatementPattern> matches = new ArrayList<>(1);
		optimized.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				if (matches.isEmpty()
						&& node.getPredicateVar() != null
						&& predicate.equals(node.getPredicateVar().getValue())
						&& node.getObjectVar() != null
						&& objectBindingName.equals(node.getObjectVar().getName())) {
					matches.add(node);
				}
				super.meet(node);
			}
		});
		return matches.isEmpty() ? null : matches.getFirst();
	}
}
